-- Clean-room baseline for local/staging rebuilds. Existing remote tables are preserved.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (row_id TEXT PRIMARY KEY,line_id TEXT UNIQUE,name TEXT NOT NULL DEFAULT '',industry TEXT NOT NULL DEFAULT '',gender TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',birthday TEXT NOT NULL DEFAULT '',region TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',socials TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'user',store_id TEXT NOT NULL DEFAULT '',referrer_id TEXT NOT NULL DEFAULT '',network_id TEXT NOT NULL DEFAULT 'admin',tg_token TEXT NOT NULL DEFAULT '',tg_chat_id TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS card_contacts (row_id TEXT PRIMARY KEY,line_id TEXT NOT NULL DEFAULT '',creator_id TEXT NOT NULL DEFAULT '',owner_user_id TEXT NOT NULL DEFAULT '',profile_user_id TEXT NOT NULL DEFAULT '',claimed_by_uid TEXT NOT NULL DEFAULT '',scanner_user_id TEXT NOT NULL DEFAULT '',source_type TEXT NOT NULL DEFAULT '',network_id TEXT NOT NULL DEFAULT 'admin',name TEXT NOT NULL DEFAULT '',mobile TEXT NOT NULL DEFAULT '',office_phone TEXT NOT NULL DEFAULT '',company_name TEXT NOT NULL DEFAULT '',title TEXT NOT NULL DEFAULT '',image_url TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activities (activity_id TEXT PRIMARY KEY,creator_id TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active',start_time TEXT NOT NULL DEFAULT '',end_time TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS registrants (registration_id TEXT PRIMARY KEY,activity_id TEXT NOT NULL DEFAULT '',line_id TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',checked_in INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS points_ledger (ledger_id TEXT PRIMARY KEY,user_id TEXT NOT NULL DEFAULT '',amount INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);